import SwiftUI

/// "Bon dia", "ola", "kaixo", "hola", "hello": the greeting of each language the app
/// offers, lettered one after another at the top of the languages screen.
///
/// The letters are a monoline script of narrow ovals (`GreetingLettering+Paths.swift`,
/// generated by `scripts/generate-greetings.py`), one pen path per word stroked with one
/// continuous orange-to-amber gradient, so no seam shows between letters. The pen writes the word
/// from start to end, it rests, and the stroke then leaves from where it began before the
/// next language writes its own. It starts with the language in use. Under Reduce Motion
/// the words only cross-fade.
struct GreetingLettering: View {
    /// Languages to greet in, in order; those without a drawn greeting are skipped.
    let languageIDs: [String]

    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var index = 0
    @State private var head: CGFloat = 0
    @State private var tail: CGFloat = 0
    @State private var opacity: Double = 1

    private static let slant = CGAffineTransform(a: 1, b: 0, c: -tan(12 * .pi / 180), d: 1, tx: 0, ty: 0)
    /// Pen width in letter units (the x-height is 100).
    private static let penWidth: CGFloat = 19
    /// The band every greeting is fitted into, in letter units: ascender loops to the
    /// baseline hooks, pen included, so all the words share one size and one baseline.
    private static let bandTop: CGFloat = -190
    private static let bandBottom: CGFloat = 16

    /// One gradient across the word, from the project's orange to its amber: one stroke,
    /// so nothing marks where a letter ends.
    private static let ink = Gradient(colors: [
        Color(red: 1, green: 0.392, blue: 0),   // #FF6400
        Color(red: 1, green: 0.69, blue: 0),    // #FFB000
    ])

    private var items: [(text: String, path: CGPath)] {
        languageIDs.compactMap { Self.greetings[$0] }
    }

    var body: some View {
        GeometryReader { proxy in
            if !items.isEmpty {
                let item = items[index % items.count]
                let fitted = Self.fit(item.path, in: proxy.size)
                let width = max(1, proxy.size.width)
                Path(fitted.path)
                    .trim(from: tail, to: head)
                    .stroke(
                        LinearGradient(
                            gradient: Self.ink,
                            startPoint: UnitPoint(x: fitted.bounds.minX / width, y: 0.5),
                            endPoint: UnitPoint(x: fitted.bounds.maxX / width, y: 0.5)
                        ),
                        style: StrokeStyle(lineWidth: Self.penWidth * fitted.scale, lineCap: .round, lineJoin: .round)
                    )
                    .opacity(opacity)
            }
        }
        .task(id: languageIDs) { await run() }
        .accessibilityHidden(true)
    }

    /// Write, rest, draw back, next; for as long as the screen is open.
    private func run() async {
        guard !items.isEmpty else { return }
        // A new list starts over with its first language (the one just chosen).
        index = 0
        while !Task.isCancelled {
            let letters = Double(items[index % items.count].text.count)
            if reduceMotion {
                set(head: 1, tail: 0)
                withAnimation(.easeInOut(duration: 0.5)) { opacity = 1 }
                guard await pause(2.8) else { return }
                withAnimation(.easeInOut(duration: 0.5)) { opacity = 0 }
                guard await pause(0.55) else { return }
            } else {
                set(head: 0, tail: 0)
                opacity = 1
                let writing = 0.9 + letters * 0.2
                withAnimation(.timingCurve(0.45, 0.05, 0.35, 1, duration: writing)) { head = 1 }
                guard await pause(writing + 1.5) else { return }
                withAnimation(.timingCurve(0.55, 0, 0.75, 0.6, duration: 0.85)) { tail = 1 }
                guard await pause(1.2) else { return }
            }
            index += 1
        }
    }

    private func set(head: CGFloat, tail: CGFloat) {
        var instant = Transaction()
        instant.disablesAnimations = true
        withTransaction(instant) {
            self.head = head
            self.tail = tail
        }
    }

    private func pause(_ seconds: Double) async -> Bool {
        try? await Task.sleep(for: .seconds(seconds))
        return !Task.isCancelled
    }

    /// The greeting slanted, scaled so the shared band fills the height (narrower if the
    /// word would not fit across), and centred. `bounds` is where the word lands.
    private static func fit(_ path: CGPath, in size: CGSize) -> (path: CGPath, scale: CGFloat, bounds: CGRect) {
        var lean = slant
        let slanted = path.copy(using: &lean) ?? path
        let bounds = slanted.boundingBoxOfPath.insetBy(dx: -penWidth / 2, dy: 0)
        let band = bandBottom - bandTop
        // The widest greeting keeps some air at the sides, clear of the close button.
        let scale = min(size.height / band, size.width * 0.62 / max(1, bounds.width))
        var place = CGAffineTransform(
            translationX: size.width / 2 - bounds.midX * scale,
            y: size.height / 2 - (bandTop + band / 2) * scale
        ).scaledBy(x: scale, y: scale)
        let placed = slanted.copy(using: &place) ?? slanted
        return (placed, scale, bounds.applying(place))
    }
}
